import{_ as p,a0 as l,w as i,s as a,ao as S,I as r,x as e,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const E=JSON.parse('{"title":"小白技巧：openSUSE設置服務服務通過防火牆 | LCTT x X-CMD","titleTemplate":false,"description":"小白技巧：openSUSE設置服務服務通過防火牆 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"小白技巧：openSUSE設置服務服務通過防火牆 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"小白技巧：openSUSE設置服務服務通過防火牆 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE","title":"小白技巧：openSUSE設置服務服務通過防火牆","tag":"201411","desc":""},"relativePath":"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE.md","filePath":"[post].md"}'),u={name:"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE.md"};function g(d,t,w,T,m,f){const n=l("Link");return i(),a("div",null,[t[13]||(t[13]=S('<h1 id="小白技巧-opensuse設置服務服務通過防火牆" tabindex="-1">小白技巧：openSUSE設置服務服務通過防火牆 <a class="header-anchor" href="#小白技巧-opensuse設置服務服務通過防火牆" aria-label="Permalink to “小白技巧：openSUSE設置服務服務通過防火牆”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE.png" alt=""></p><p>正如你所知道的，在openSUSE/SUSE系統上，不是所有的服務是激活並且默認允許的。例如，<strong>ssh</strong>服務是默認不允許通過防火牆的。當然，這是一個安全措施，但是有時我們必須需要ssh服務從遠程地點來連接服務器。</p><p>這個小教程將會展示如何允許服務，不單是ssh，也包括所有其他的服務，如http，ftp等，通過服務器。我們可以使用<strong>YaST</strong>命令允許服務通過防火牆，<strong>YaST</strong>命令是openSUSE和其企業版，默認安裝配置工具。</p><p>首先，在菜單中打開YaST控制中心。選擇<strong>Security and Users（安全和用户） -&gt; Firewall（防火牆）</strong></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE-13.1-Running-Oracle-VM-VirtualBox_001.png" alt=""></p><p>接下來，打開<strong>Allowed Services（已允許服務）</strong>選項卡；從Service to Allow（選擇需要允許的服務）下拉框中選擇<strong>Secure Shell Service（ssh服務）</strong>，然後 <strong>Add（增加）</strong>，<strong>Next（下一步）</strong>，最後<strong>Finish（完成）</strong>，搞定。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE-13.1-Running-Oracle-VM-VirtualBox_002.png" alt=""></p><p>就是如此簡單！ssh服務已經允許通過防火牆，這樣你就可以在遠程系統連接這個系統了。就像這樣，我們可以同樣設置其他服務。</p><p>鼓掌！！</p><hr>',11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.unixmen.com/quick-tip-allow-services-firewall-opensuse/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/quick-tip-allow-services-firewall-opensuse/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),o(n,{href:"http://www.unixmen.com/author/sk/"},{default:s(()=>[...t[2]||(t[2]=[e("SK",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),o(n,{href:"http://www.vicyu.net"},{default:s(()=>[...t[3]||(t[3]=[e("VicYu/Vic020",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const U=p(u,[["render",g]]);export{E as __pageData,U as default};
